css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .intro{font-size: 13px; font-family: sans-serif; font-weight: 600; color: #444; margin-bottom: 13px;}
.mz .problema{border: 1.8px solid var(--bosque); border-radius: 10px; padding: 13px 15px; margin-bottom: 22px; font-size: 15px; line-height: 1.45;}
.mz .problema .pnum{font-family: sans-serif; font-weight: 800; margin-right: 5px;}
.mz .problema .op-line{display: flex; align-items: center; gap: 10px; margin-top: 14px; font-size: 15px; font-weight: 700; font-family: sans-serif;}
.mz .problema .op-line .et{font-family: sans-serif; font-size: 12px; color: #555;}
.mz .problema .caja{width: 70px; height: 30px; border: 1.6px dashed #000; border-radius: 6px; display: inline-block;}
.mz .problema .sol{border-bottom: 1.5px solid var(--bosque); flex: 1; min-height: 22px;}
.mz .problema{line-height: 1.725 !important;}
